const std = @import("std");

pub fn main() !void {
    const keys = [_][]const u8{
        "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"
    };
    const word = "zig";

    for (word) |ch| {
        var digit: u8 = 0;
        for (keys, 2..) |letters, num| {
            for (letters) |l| {
                if (l == ch) digit = @intCast(num);
            }
        }
        if (digit > 0) std.debug.print("{}", .{digit});
    }
    std.debug.print("\n", .{});
}
